
import React, { useEffect, useState, useRef } from 'react';
import { useAppState, useAppDispatch } from '../hooks/useAppStore';
import { Order, OrderStatus } from '../types';

const NOTIFICATION_SOUND_URL = 'data:audio/mpeg;base64,-AAA';

const OrderCard: React.FC<{ order: Order; isNew: boolean }> = ({ order, isNew }) => {
    const dispatch = useAppDispatch();

    const handleServeOrder = () => {
        dispatch({ type: 'UPDATE_ORDER_STATUS', payload: { orderId: order.id, status: OrderStatus.Served } });
    };

    const cardClasses = [
        "bg-brand-surface",
        "rounded-lg",
        "shadow-xl",
        "p-6",
        "flex",
        "flex-col",
        "justify-between",
        "transition-all",
        "duration-300",
        isNew ? "border-4 border-green-500 animate-pulse" : ""
    ].join(" ");

    return (
        <div className={cardClasses}>
            <div>
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-2xl font-bold text-brand-primary">โต๊ะ {order.tableNumber}</h3>
                    <span className="text-sm text-gray-500">{new Date(order.timestamp).toLocaleTimeString()}</span>
                </div>
                <ul className="space-y-3 mb-4">
                    {order.items.map(item => (
                        <li key={item.id} className="text-brand-dark bg-gray-50 p-2 rounded-md">
                            <div className="flex justify-between">
                                <span className="font-medium">{item.name}</span>
                                <span className="font-bold">x{item.quantity}</span>
                            </div>
                            {item.note && (
                                <p className="text-sm text-yellow-900 mt-1 pl-2 border-l-4 border-yellow-400">
                                    <span className="font-semibold">หมายเหตุ:</span> {item.note}
                                </p>
                            )}
                        </li>
                    ))}
                </ul>
            </div>
            <button
                onClick={handleServeOrder}
                className="w-full mt-6 bg-brand-primary text-white font-bold py-3 px-4 rounded-lg hover:bg-opacity-80 transition-colors"
            >
                พร้อมเสิร์ฟ
            </button>
        </div>
    );
};

const KitchenPage: React.FC = () => {
    const { orders } = useAppState();
    const [newOrderIds, setNewOrderIds] = useState<string[]>([]);
    const prevActiveOrderIdsRef = useRef<Set<string>>(new Set());
    const isInitialMount = useRef(true);

    const activeOrders = orders.filter(order => order.status === OrderStatus.Placed);

    useEffect(() => {
        const currentActiveOrderIds = new Set(activeOrders.map(o => o.id));

        if (isInitialMount.current) {
            isInitialMount.current = false;
        } else {
            const newlyAddedIds = [...currentActiveOrderIds].filter(id => !prevActiveOrderIdsRef.current.has(id));
            
            if (newlyAddedIds.length > 0) {
                // Play sound notification
                const audio = new Audio(NOTIFICATION_SOUND_URL);
                audio.play().catch(e => console.error("Error playing sound:", e));

                // Set visual alert
                setNewOrderIds(current => [...current, ...newlyAddedIds]);
                
                // Remove visual alert after some time
                setTimeout(() => {
                    setNewOrderIds(current => current.filter(id => !newlyAddedIds.includes(id)));
                }, 5000); // Alert lasts for 5 seconds
            }
        }
        
        prevActiveOrderIdsRef.current = currentActiveOrderIds;

    }, [activeOrders]);

    return (
        <div className="container mx-auto">
            <h1 className="text-3xl font-bold text-brand-primary mb-6">รายการอาหาร (ครัว)</h1>
            {activeOrders.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {activeOrders.sort((a, b) => a.timestamp - b.timestamp).map(order => (
                        <OrderCard key={order.id} order={order} isNew={newOrderIds.includes(order.id)} />
                    ))}
                </div>
            ) : (
                <div className="text-center py-20 bg-brand-surface rounded-lg shadow-md">
                    <p className="text-2xl text-gray-400">ไม่มีรายการสั่งซื้อในขณะนี้</p>
                </div>
            )}
        </div>
    );
};

export default KitchenPage;
